CREATE TABLE projects(project_id TEXT PRIMARY KEY, revision BIGINT NOT NULL CHECK(revision>0), paused BOOLEAN NOT NULL DEFAULT false, archived BOOLEAN NOT NULL DEFAULT false, authority_mode TEXT NOT NULL CHECK(authority_mode IN('MANAGED','OBSERVED_READ_ONLY')), event_seq BIGINT NOT NULL DEFAULT 0, data JSONB NOT NULL);
CREATE TABLE project_revisions(project_id TEXT NOT NULL REFERENCES projects, revision BIGINT NOT NULL, data JSONB NOT NULL, PRIMARY KEY(project_id,revision));
CREATE TABLE requirements(project_id TEXT NOT NULL REFERENCES projects, requirement_id TEXT NOT NULL, revision BIGINT NOT NULL CHECK(revision>0), data JSONB NOT NULL, PRIMARY KEY(project_id,requirement_id));
CREATE TABLE owner_nodes(project_id TEXT NOT NULL REFERENCES projects, owner_id TEXT NOT NULL, parent_id TEXT, paused BOOLEAN NOT NULL DEFAULT false, data JSONB NOT NULL, PRIMARY KEY(project_id,owner_id), FOREIGN KEY(project_id,parent_id) REFERENCES owner_nodes(project_id,owner_id));
CREATE TABLE owner_closure(project_id TEXT NOT NULL, ancestor_id TEXT NOT NULL, descendant_id TEXT NOT NULL, depth INTEGER NOT NULL CHECK(depth>=0), PRIMARY KEY(project_id,ancestor_id,descendant_id), FOREIGN KEY(project_id,ancestor_id) REFERENCES owner_nodes(project_id,owner_id), FOREIGN KEY(project_id,descendant_id) REFERENCES owner_nodes(project_id,owner_id));
CREATE TABLE flow_revisions(project_id TEXT NOT NULL REFERENCES projects, flow_revision BIGINT NOT NULL CHECK(flow_revision>0), revision BIGINT NOT NULL CHECK(revision>0), state TEXT NOT NULL CHECK(state IN('DRAFT','CHECKING','REVIEW_REQUIRED','COMMITTED','SUPERSEDED')), input_digest TEXT NOT NULL, data JSONB NOT NULL, PRIMARY KEY(project_id,flow_revision));
CREATE TABLE tasks(project_id TEXT NOT NULL, task_id TEXT NOT NULL, task_revision BIGINT NOT NULL CHECK(task_revision>0), flow_revision BIGINT NOT NULL, team_id TEXT NOT NULL, owner_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('PLANNED','NEEDS_REVIEW','READY_FOR_ADMISSION','DEFERRED','REMOVED_FROM_PLAN')), input_digest TEXT NOT NULL, fence_epoch BIGINT NOT NULL DEFAULT 0 CHECK(fence_epoch>=0), revision BIGINT NOT NULL, data JSONB NOT NULL, PRIMARY KEY(project_id,task_id), FOREIGN KEY(project_id,flow_revision) REFERENCES flow_revisions(project_id,flow_revision), FOREIGN KEY(project_id,team_id) REFERENCES owner_nodes(project_id,owner_id), FOREIGN KEY(project_id,owner_id) REFERENCES owner_nodes(project_id,owner_id));
CREATE TABLE task_revisions(project_id TEXT NOT NULL,task_id TEXT NOT NULL,task_revision BIGINT NOT NULL,data JSONB NOT NULL,PRIMARY KEY(project_id,task_id,task_revision),FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,task_id));
CREATE TABLE task_dependencies(project_id TEXT NOT NULL,flow_revision BIGINT NOT NULL,task_id TEXT NOT NULL,dependency_id TEXT NOT NULL,PRIMARY KEY(project_id,flow_revision,task_id,dependency_id),CHECK(task_id<>dependency_id),FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,task_id),FOREIGN KEY(project_id,dependency_id) REFERENCES tasks(project_id,task_id),FOREIGN KEY(project_id,flow_revision) REFERENCES flow_revisions(project_id,flow_revision));
CREATE TABLE attempts(project_id TEXT NOT NULL,attempt_id TEXT PRIMARY KEY,task_id TEXT NOT NULL,task_revision BIGINT NOT NULL,lease_id TEXT NOT NULL UNIQUE,generation BIGINT NOT NULL CHECK(generation>0),worker_id TEXT NOT NULL,operation_id TEXT NOT NULL UNIQUE,state TEXT NOT NULL CHECK(state IN('LEASED','STARTING','RUNNING','VERIFYING','REVIEW_READY','MERGE_QUEUED','MERGING','STOPPING','RECOVERY_REQUIRED','SUCCEEDED','FAILED','CANCELLED')),revision BIGINT NOT NULL CHECK(revision>0),created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),terminal_at TIMESTAMPTZ,data JSONB NOT NULL,envelope JSONB NOT NULL, UNIQUE(project_id,attempt_id),FOREIGN KEY(project_id,task_id,task_revision) REFERENCES task_revisions(project_id,task_id,task_revision));
CREATE UNIQUE INDEX one_open_attempt_per_task ON attempts(project_id,task_id) WHERE terminal_at IS NULL;
CREATE TABLE leases(project_id TEXT NOT NULL,lease_id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL,generation BIGINT NOT NULL,worker_id TEXT NOT NULL,capability_scope JSONB NOT NULL,issued_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,token_digest TEXT, UNIQUE(attempt_id,generation),FOREIGN KEY(project_id,attempt_id) REFERENCES attempts(project_id,attempt_id),CHECK(expires_at>issued_at));
CREATE TABLE resource_scopes(scope_id TEXT PRIMARY KEY,parent_scope_id TEXT REFERENCES resource_scopes,project_id TEXT REFERENCES projects,team_id TEXT,revision BIGINT NOT NULL CHECK(revision>0),paused BOOLEAN NOT NULL DEFAULT false,data JSONB NOT NULL,FOREIGN KEY(project_id,team_id) REFERENCES owner_nodes(project_id,owner_id));
CREATE TABLE resource_limits(scope_id TEXT NOT NULL REFERENCES resource_scopes,dimension TEXT NOT NULL CHECK(dimension IN('active_slot','coding_slot','cpu_units','memory_bytes','build_permit','gpu_permit','provider_inflight')),hard_limit BIGINT NOT NULL CHECK(hard_limit>=0),allocated BIGINT NOT NULL DEFAULT 0 CHECK(allocated>=0),PRIMARY KEY(scope_id,dimension));
CREATE TABLE resource_allocations(allocation_id TEXT PRIMARY KEY,project_id TEXT NOT NULL,attempt_id TEXT NOT NULL,scope_id TEXT NOT NULL,dimension TEXT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),state TEXT NOT NULL CHECK(state IN('RESERVED','HELD','QUARANTINED','RELEASED')),acquired_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),released_at TIMESTAMPTZ,release_reason TEXT,UNIQUE(attempt_id,scope_id,dimension),FOREIGN KEY(project_id,attempt_id) REFERENCES attempts(project_id,attempt_id),FOREIGN KEY(scope_id,dimension) REFERENCES resource_limits(scope_id,dimension));
CREATE TABLE events(event_id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects,project_seq BIGINT NOT NULL CHECK(project_seq>0),object_id TEXT NOT NULL,object_revision BIGINT NOT NULL,schema_version TEXT NOT NULL,kind TEXT NOT NULL,payload JSONB NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),UNIQUE(project_id,project_seq));
CREATE TABLE outbox(outbox_id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects,operation_id TEXT NOT NULL,kind TEXT NOT NULL,payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),delivered_at TIMESTAMPTZ,UNIQUE(operation_id,kind));
CREATE TABLE idempotency_records(actor_id TEXT NOT NULL,operation TEXT NOT NULL,idempotency_key TEXT NOT NULL,operation_id TEXT NOT NULL UNIQUE,request JSONB NOT NULL,response JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(actor_id,operation,idempotency_key));
CREATE TABLE evidence_receipts(project_id TEXT NOT NULL,receipt_id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL,generation BIGINT NOT NULL,kind TEXT NOT NULL,data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL,FOREIGN KEY(project_id,attempt_id) REFERENCES attempts(project_id,attempt_id));
CREATE TABLE merge_intents(intent_id TEXT PRIMARY KEY,project_id TEXT NOT NULL,attempt_id TEXT NOT NULL,generation BIGINT NOT NULL,target_ref TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('PREPARED','COMMIT_DECIDED','COMMITTED','ABORTED','RECOVERY_REQUIRED')),revision BIGINT NOT NULL,data JSONB NOT NULL,FOREIGN KEY(project_id,attempt_id) REFERENCES attempts(project_id,attempt_id));
CREATE UNIQUE INDEX one_unresolved_merge_per_ref ON merge_intents(project_id,target_ref) WHERE state IN('PREPARED','COMMIT_DECIDED','RECOVERY_REQUIRED');
CREATE TABLE work_packages(project_id TEXT NOT NULL REFERENCES projects,work_package_id TEXT NOT NULL,data JSONB NOT NULL,PRIMARY KEY(project_id,work_package_id));
CREATE TABLE context_manifests(project_id TEXT NOT NULL REFERENCES projects,manifest_id TEXT NOT NULL,sha256 TEXT NOT NULL,data JSONB NOT NULL,PRIMARY KEY(project_id,manifest_id));
CREATE TABLE contract_versions(project_id TEXT NOT NULL REFERENCES projects,contract_id TEXT NOT NULL,version BIGINT NOT NULL,state TEXT NOT NULL CHECK(state IN('DRAFT','FROZEN','SUPERSEDED')),data JSONB NOT NULL,PRIMARY KEY(project_id,contract_id,version));
CREATE TABLE contract_consumers(project_id TEXT NOT NULL,contract_id TEXT NOT NULL,version BIGINT NOT NULL,task_id TEXT NOT NULL,receipt_id TEXT,data JSONB NOT NULL,PRIMARY KEY(project_id,contract_id,version,task_id),FOREIGN KEY(project_id,contract_id,version) REFERENCES contract_versions,FOREIGN KEY(project_id,task_id) REFERENCES tasks);
CREATE TABLE provider_requests(project_id TEXT NOT NULL,request_id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL,data JSONB NOT NULL,FOREIGN KEY(project_id,attempt_id) REFERENCES attempts(project_id,attempt_id));
CREATE TABLE worktrees(project_id TEXT NOT NULL,worktree_id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL,path TEXT NOT NULL UNIQUE,data JSONB NOT NULL,FOREIGN KEY(project_id,attempt_id) REFERENCES attempts(project_id,attempt_id));
CREATE TABLE gate_runs(project_id TEXT NOT NULL REFERENCES projects,gate_run_id TEXT PRIMARY KEY,status TEXT NOT NULL CHECK(status IN('NOT_RUN','BLOCKED','INCONCLUSIVE','FAIL','PASS','VERIFIER_INVALID')),data JSONB NOT NULL);
CREATE TABLE artifacts(project_id TEXT NOT NULL REFERENCES projects,artifact_id TEXT PRIMARY KEY,sha256 TEXT NOT NULL CHECK(length(sha256)=64),data JSONB NOT NULL);
CREATE TABLE source_snapshots(project_id TEXT NOT NULL REFERENCES projects,snapshot_id TEXT PRIMARY KEY,data JSONB NOT NULL);
CREATE INDEX events_replay ON events(project_id,project_seq);
CREATE INDEX outbox_pending ON outbox(created_at) WHERE delivered_at IS NULL;
CREATE INDEX attempts_project_state ON attempts(project_id,state);
CREATE INDEX leases_expiry ON leases(expires_at) WHERE revoked_at IS NULL;
CREATE TABLE documents(project_id TEXT NOT NULL REFERENCES projects,collection TEXT NOT NULL,document_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),data JSONB NOT NULL,PRIMARY KEY(project_id,collection,document_id));
CREATE TABLE workers(worker_id TEXT PRIMARY KEY,boot_id TEXT NOT NULL,capabilities JSONB NOT NULL,heartbeat_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),active_attempt_ids JSONB NOT NULL DEFAULT '[]');
CREATE TABLE worker_event_ids(event_id TEXT PRIMARY KEY,project_id TEXT NOT NULL,attempt_id TEXT NOT NULL,payload JSONB NOT NULL,FOREIGN KEY(project_id,attempt_id) REFERENCES attempts(project_id,attempt_id));
ALTER TABLE outbox ADD COLUMN claimed_by TEXT REFERENCES workers(worker_id);
CREATE TABLE gateway_scope_budget(token_sha256 TEXT PRIMARY KEY CHECK(length(token_sha256)=64),attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),route_id TEXT NOT NULL,model TEXT NOT NULL,max_requests BIGINT NOT NULL CHECK(max_requests>0),inflight_limit BIGINT NOT NULL CHECK(inflight_limit>0),requests_used BIGINT NOT NULL DEFAULT 0 CHECK(requests_used>=0),inflight BIGINT NOT NULL DEFAULT 0 CHECK(inflight>=0),expires_at TIMESTAMPTZ NOT NULL,revoked BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE model_request_permit(request_id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),route_id TEXT NOT NULL,model TEXT NOT NULL,generation BIGINT NOT NULL,admitted_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),status TEXT NOT NULL,settlement JSONB);
ALTER TABLE gateway_scope_budget ADD COLUMN project_id TEXT NOT NULL REFERENCES projects(project_id);
ALTER TABLE gateway_scope_budget ADD COLUMN generation BIGINT NOT NULL CHECK(generation>0);
ALTER TABLE gateway_scope_budget ADD CONSTRAINT gateway_attempt_route_unique UNIQUE(attempt_id,route_id);
ALTER TABLE model_request_permit ADD COLUMN scope_token_digest TEXT NOT NULL REFERENCES gateway_scope_budget(token_sha256);
